fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars_rev = txt.chars().rev();

    // Get the last character
    let last_char = match chars_rev.next() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check if last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check the character before the last (if any)
    match chars_rev.next() {
        None => true,               // single character string, last is ascii letter → true
        Some(prev_char) => prev_char == ' ', // true if prev char is space, else false
    }
}